INSERT INTO recruitment_questions (id,text,options,correct_option,category,difficulty,active,version,updated_at) SELECT 'c67bfa44-f4e0-593b-8d99-3fbeecf41a37','Trước khi nhận công việc, partner cần kiểm tra điều gì?','["Phạm vi công việc, địa điểm và thời gian đã đặt", "Chỉ xem số tiền", "Nhận trước rồi tìm hiểu sau", "Chỉ xem tên khách hàng"]',0,'Quy trình làm việc',2,true,0,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM recruitment_questions WHERE id='c67bfa44-f4e0-593b-8d99-3fbeecf41a37');
INSERT INTO recruitment_questions (id,text,options,correct_option,category,difficulty,active,version,updated_at) SELECT 'e72cde0c-7282-5926-80a3-94ef3348914a','Nếu dự kiến đến muộn, partner nên làm gì?','["Chờ khách gọi mới báo", "Thông báo sớm qua kênh liên hệ của công việc và cập nhật thời gian dự kiến", "Không cần báo nếu muộn ít", "Đánh dấu đã đến để tránh bị muộn"]',1,'Giao tiếp',2,true,0,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM recruitment_questions WHERE id='e72cde0c-7282-5926-80a3-94ef3348914a');
